        .get(&slot)
        .copied()
        .ok_or_else(|| missing_slot(poisoned, &slot, "export"))?;
    let entry = parked
        .get_mut(&park_id)
        .ok_or_else(|| format!("parked fragment vanished under {slot:?}"))?;
    let batch = entry
        .fragment
        .export_packed(stream)
        .map_err(|err| format!("failed to export a packed batch for {slot:?}: {err}"))?;
